"  const getPrepTimeLabel = (createdAt) => {
    if (!createdAt) return "Prep. Time: 30:00";
    const elapsedMs = Date.now() - new Date(createdAt).getTime();
    const totalPrepMs = 30 * 60 * 1000; // 30 minutes prep time
    const remainingMs = totalPrepMs - elapsedMs;
    if (remainingMs <= 0) return "Prep. Time: Overdue";
    const mins = Math.floor(remainingMs / 60000);
    const secs = Math.floor((remainingMs % 60000) / 1000);
    return `Prep. Time: ${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const getStatusStepIndex = (status) => {
    const s = String(status || 'PENDING').toUpperCase();
    if (s === 'COMPLETED') return 3;
    if (['DISPATCHED', 'READY', 'FOOD READY'].includes(s)) return 2;
    if (['PROCESSING', 'PREPARING'].includes(s)) return 1;
    return 0;
  };"

